func (q *Queries) SetCover(ctx context.Context, arg SetCoverParams) error {
	_, err := q.db.ExecContext(ctx, setCover,
		arg.CoverImage,
		arg.CoverError,
		arg.UpdatedAt,
		arg.ID,
	)
	return err
}

const sourceTitlesOf = `-- name: SourceTitlesOf :many
SELECT st.title_id, st.id, s.slug, st.url, st.lang, s.hosted, h.reading_mode, h.rights
FROM source_titles st JOIN sources s ON s.id = st.source_id
LEFT JOIN hosted_source_titles h ON h.source_title_id = st.id
WHERE st.title_id IN (/*SLICE:ids*/?) ORDER BY st.title_id, s.hosted DESC, st.position
`

type SourceTitlesOfRow struct {
	TitleID     int64
	ID          int64
	Slug        string
	Url         string
	Lang        string
	Hosted      int64
	ReadingMode sql.NullString
	Rights      sql.NullString
}

func (q *Queries) SourceTitlesOf(ctx context.Context, ids []int64) ([]SourceTitlesOfRow, error) {
	query := sourceTitlesOf
	var queryParams []interface{}
	if len(ids) > 0 {
		for _, v := range ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SourceTitlesOfRow{}
	for rows.Next() {
		var i SourceTitlesOfRow
		if err := rows.Scan(
			&i.TitleID,
			&i.ID,
			&i.Slug,
			&i.Url,
			&i.Lang,
			&i.Hosted,
			&i.ReadingMode,
			&i.Rights,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

